const interestTerms = ['interesse', 'interessante', 'gostaria', 'vamos conversar', 'podemos conversar', 'tenho interesse'];
const budgetTerms = ['orçamento', 'orcamento', 'preço', 'preco', 'valor', 'verba', 'investimento', 'quanto custa'];
const meetingTerms = ['reunião', 'reuniao', 'call', 'conversa', 'agenda', 'agendar', 'disponibilidade', 'horário', 'horario'];
const negotiationTerms = ['proposta', 'prazo', 'escopo', 'contrato', 'condições', 'condicoes', 'ajuste', 'negociar', 'fechar'];
const refusalTerms = ['não tenho interesse', 'nao tenho interesse', 'não queremos', 'nao queremos', 'já resolvemos', 'ja resolvemos', 'recusar', 'recusado'];
const optOutTerms = ['não entrar em contato', 'nao entrar em contato', 'remover', 'remova', 'não quero receber', 'nao quero receber', 'unsubscribe', 'stop', 'pare de enviar'];
const headerValue = (item, name) => { const headers = Array.isArray(item.headers) ? item.headers : []; const found = headers.find((header) => String(header.name || '').toLowerCase() === name.toLowerCase()); return found ? String(found.value || '') : ''; };
const textOf = (item) => [item.subject, item.snippet, item.textPlain, item.text, item.body, headerValue(item, 'Subject')].filter(Boolean).join(' ').toLocaleLowerCase('pt-BR');
const senderOf = (item) => String(item.from || item.sender || headerValue(item, 'From') || '').trim();
const hasLabel = (item, label) => Array.isArray(item.labelIds) && item.labelIds.some((value) => String(value).toUpperCase() === label);
const messages = $input.all().map((item) => item.json);
const sentThreads = new Set(messages.filter((item) => hasLabel(item, 'SENT')).map((item) => String(item.threadId || item.thread_id || '')).filter(Boolean));
const seen = new Set();
const incoming = messages.filter((item) => {
  const id = String(item.id || item.messageId || '');
  const threadId = String(item.threadId || item.thread_id || '');
  const sender = senderOf(item).toLowerCase();
  if (!id || seen.has(id)) return false;
  seen.add(id);
  return threadId && sentThreads.has(threadId) && !hasLabel(item, 'SENT') && !sender.includes('me');
});
return incoming.map((item) => {
  const text = textOf(item);
  const matches = (terms) => terms.filter((term) => text.includes(term));
  const interest = matches(interestTerms);
  const budget = matches(budgetTerms);
  const meeting = matches(meetingTerms);
  const negotiation = matches(negotiationTerms);
  const refusal = matches(refusalTerms);
  const optOut = matches(optOutTerms);
  const categories = [];
  if (interest.length) categories.push('interesse');
  if (budget.length) categories.push('orcamento');
  if (meeting.length) categories.push('reuniao');
  if (negotiation.length) categories.push('negociacao');
  if (refusal.length) categories.push('recusa');
  if (optOut.length) categories.push('nao_contato');
  const priority = optOut.length || budget.length || meeting.length || negotiation.length ? 'alta' : categories.length ? 'media' : 'baixa';
  return { json: { source: 'gmail', thread_id: String(item.threadId || item.thread_id), message_id: String(item.id || item.messageId), sender: senderOf(item) || 'não identificado', subject: String(item.subject || headerValue(item, 'Subject') || 'sem assunto'), excerpt: String(item.snippet || item.textPlain || item.text || '').replace(/\s+/g, ' ').trim().slice(0, 1000), categories, matched_terms: [...new Set([...interest, ...budget, ...meeting, ...negotiation, ...refusal, ...optOut])], priority, opt_out_signal: Boolean(optOut.length), alert_title: optOut.length ? 'AÇÃO IMEDIATA: pedido de não contato' : `Resposta comercial ${priority}: ${String(item.subject || 'sem assunto').slice(0, 100)}` } };
}).filter(({ json }) => json.categories.length > 0);

const seenAlerts = new Set();
return $input.all().filter(({ json }) => {
  const key = `${json.message_id}:${json.thread_id}`;
  if (seenAlerts.has(key)) return false;
  seenAlerts.add(key);
  return true;
}).map(({ json }) => ({ json: { alert_key: `${json.message_id}:${json.thread_id}`, alert_type: json.opt_out_signal ? 'SUPRESSAO_URGENTE' : 'OPORTUNIDADE_COMERCIAL', alert_title: json.alert_title, priority: json.priority, categories: json.categories, sender: json.sender, subject: json.subject, thread_id: json.thread_id, message_id: json.message_id, matched_terms: json.matched_terms, excerpt: json.excerpt, action_required: json.opt_out_signal ? 'Adicionar o remetente à lista de supressão antes da próxima execução e não responder automaticamente.' : 'Revisar manualmente a conversa no Gmail antes de qualquer resposta.' } }));
